"""
Investigation Report Generator for Digital Time Machine.
Generates structured investigation reports synthesizing observed evidence, correlation findings,
ghost evidence anomalies, and evidence file hashes with forensic caveats.
"""

from datetime import datetime

REPORT_DISCLAIMER = (
    "DISCLAIMER: This report is generated by Digital Time Machine as an investigative aid for forensic triage. "
    "Correlation findings, anomaly detections, and reconstructed timelines reflect synthetic rule matches and "
    "heuristics derived strictly from the ingested evidence dataset. They DO NOT constitute definitive legal proof of "
    "malicious intent, criminal activity, or actor identity. All observations must be verified by certified forensic "
    "examiners against underlying binary disk images, non-volatile artifacts, and official authorization policies."
)

def generate_investigation_report_data(
    case: dict,
    events: list[dict],
    evidence_files: list[dict],
    correlation_findings: list[dict],
    ghost_findings: list[dict],
    notes: list[dict] = None
) -> dict:
    """
    Compiles full investigative report payload for rendering or export.
    """
    notes = notes or []
    sorted_events = sorted(events, key=lambda x: x["timestamp"])

    time_range_start = sorted_events[0]["timestamp"] if sorted_events else "N/A"
    time_range_end = sorted_events[-1]["timestamp"] if sorted_events else "N/A"

    # Source breakdown
    source_counts = {}
    severity_counts = {"low": 0, "medium": 0, "high": 0, "critical": 0}
    observed_count = 0
    inferred_count = 0

    for ev in sorted_events:
        src = ev.get("source", "unknown")
        source_counts[src] = source_counts.get(src, 0) + 1
        sev = ev.get("severity", "low").lower()
        if sev in severity_counts:
            severity_counts[sev] += 1
        if ev.get("confidence") == "observed":
            observed_count += 1
        else:
            inferred_count += 1

    # Key timeline milestones
    milestones = []
    for ev in sorted_events:
        if ev.get("severity") in ("high", "critical") or ev.get("event_type") in ("LOGIN_SUCCESS", "FILE_DOWNLOAD", "DEVICE_CONNECT", "FILE_COPY", "NETWORK_TRANSFER"):
            milestones.append(ev)

    return {
        "report_id": f"REP-{case.get('id', 'CASE')}-{datetime.now().strftime('%Y%m%d%H%M%S')}",
        "generated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S UTC"),
        "case": case,
        "disclaimer": REPORT_DISCLAIMER,
        "investigation_time_range": {
            "start": time_range_start,
            "end": time_range_end
        },
        "statistics": {
            "total_events": len(sorted_events),
            "observed_events": observed_count,
            "inferred_events": inferred_count,
            "evidence_files_count": len(evidence_files),
            "correlation_findings_count": len(correlation_findings),
            "ghost_anomalies_count": len(ghost_findings),
            "source_counts": source_counts,
            "severity_counts": severity_counts
        },
        "evidence_files": evidence_files,
        "key_milestones": milestones,
        "all_events": sorted_events,
        "correlation_findings": correlation_findings,
        "ghost_evidence_findings": ghost_findings,
        "investigation_notes": notes
    }

